    "sha256": "d1a8d9ebb870b061d389fce65f6a81f59f19ff027bd345a0d1a54a2481da24f6",
    "edits": [
      {
        "old": "      sing-box\n",
        "new": "      sing-box-polaris\n"
      }
    ]
  }
];
  return {
    name: "polaris-dashboard-branding",
    enforce: "pre",
    transform(code, id) {
